  if (scene.enterAt === undefined || scene.enterFrames === undefined) return 1;
  const enterAt = scene.enterAt;
  const enterFrames = scene.enterFrames;
  const [x1, y1, x2, y2] = scene.bezier ?? [0, 0, 1, 1];
